import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import { FaCalendarPlus, FaMagic, FaList } from "react-icons/fa";
import AlertBox from "./AlertBox";

function Planner() {
  const userId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [plans, setPlans] = useState([]);
  const [alert, setAlert] = useState(null);

  const [manualForm, setManualForm] = useState({
    course_id: "",
    study_date: "",
    topic: ""
  });

  const [autoForm, setAutoForm] = useState({
    course_id: "",
    start_date: "",
    topics: ""
  });

  const fetchData = useCallback(async () => {
    try {
      const coursesRes = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = coursesRes.data.courses || [];

      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );

      const enrolledIds = enrollRes.data.map((e) => e.course_id);
      const myCourses = allCourses.filter((c) => enrolledIds.includes(c.id));
      setCourses(myCourses);

      const plansRes = await axios.get(
        `http://127.0.0.1:8000/planner/${userId}`
      );
      setPlans(plansRes.data.plans || []);

      const progressRes = await axios.get(
        `http://127.0.0.1:8000/progress/${userId}`
      );

      const progressMap = {};
      (progressRes.data.progress || []).forEach((item) => {
        progressMap[item.course_id] = {
          completed_topics: item.completed_topics,
          total_topics: item.total_topics,
          status: item.status
        };
      });

      console.log("Progress loaded:", progressMap);
    } catch (error) {
      console.error("Planner fetch error:", error);
    }
  }, [userId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleManualChange = (e) => {
    setManualForm({
      ...manualForm,
      [e.target.name]: e.target.value
    });
  };

  const handleAutoChange = (e) => {
    setAutoForm({
      ...autoForm,
      [e.target.name]: e.target.value
    });
  };

  const handleManualSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        user_id: parseInt(userId),
        course_id: parseInt(manualForm.course_id),
        study_date: manualForm.study_date,
        topic: manualForm.topic
      };

      const response = await axios.post(
        "http://127.0.0.1:8000/create-plan",
        payload
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      setManualForm({
        course_id: "",
        study_date: "",
        topic: ""
      });

      fetchData();
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Failed to create manual plan",
        type: "error"
      });
    }
  };

  const handleAutoSubmit = async (e) => {
    e.preventDefault();

    try {
      const topicsArray = autoForm.topics
        .split(",")
        .map((item) => item.trim())
        .filter((item) => item !== "");

      const payload = {
        user_id: parseInt(userId),
        course_id: parseInt(autoForm.course_id),
        start_date: autoForm.start_date,
        topics: topicsArray
      };

      const response = await axios.post(
        "http://127.0.0.1:8000/auto-plan",
        payload
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      setAutoForm({
        course_id: "",
        start_date: "",
        topics: ""
      });

      fetchData();
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Failed to create auto plan",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2 style={{ color: "#4a148c", marginBottom: "20px" }}>
        Study Planner
      </h2>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "25px",
          marginBottom: "30px"
        }}
      >
        <div
          style={{
            background: "#f9f5ff",
            borderRadius: "16px",
            padding: "20px",
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
          }}
        >
          <h3 style={{ color: "#6a1b9a", display: "flex", gap: "10px", alignItems: "center" }}>
            <FaCalendarPlus />
            Manual Plan
          </h3>

          <form
            onSubmit={handleManualSubmit}
            style={{ display: "flex", flexDirection: "column", gap: "12px", marginTop: "15px" }}
          >
            <select
              name="course_id"
              value={manualForm.course_id}
              onChange={handleManualChange}
              style={{ padding: "12px", borderRadius: "10px" }}
            >
              <option value="">Select Course</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title}
                </option>
              ))}
            </select>

            <input
              type="date"
              name="study_date"
              value={manualForm.study_date}
              onChange={handleManualChange}
              style={{ padding: "12px", borderRadius: "10px" }}
            />

            <input
              type="text"
              name="topic"
              placeholder="Topic"
              value={manualForm.topic}
              onChange={handleManualChange}
              style={{ padding: "12px", borderRadius: "10px" }}
            />

            <button
              type="submit"
              style={{
                background: "#7b1fa2",
                color: "#fff",
                border: "none",
                padding: "12px",
                borderRadius: "10px",
                cursor: "pointer"
              }}
            >
              Create Plan
            </button>
          </form>
        </div>

        <div
          style={{
            background: "#fff8e1",
            borderRadius: "16px",
            padding: "20px",
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
          }}
        >
          <h3 style={{ color: "#ef6c00", display: "flex", gap: "10px", alignItems: "center" }}>
            <FaMagic />
            Auto Plan
          </h3>

          <form
            onSubmit={handleAutoSubmit}
            style={{ display: "flex", flexDirection: "column", gap: "12px", marginTop: "15px" }}
          >
            <select
              name="course_id"
              value={autoForm.course_id}
              onChange={handleAutoChange}
              style={{ padding: "12px", borderRadius: "10px" }}
            >
              <option value="">Select Course</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title}
                </option>
              ))}
            </select>

            <input
              type="date"
              name="start_date"
              value={autoForm.start_date}
              onChange={handleAutoChange}
              style={{ padding: "12px", borderRadius: "10px" }}
            />

            <textarea
              name="topics"
              placeholder="Enter topics separated by comma"
              value={autoForm.topics}
              onChange={handleAutoChange}
              rows="4"
              style={{ padding: "12px", borderRadius: "10px" }}
            />

            <button
              type="submit"
              style={{
                background: "#ef6c00",
                color: "#fff",
                border: "none",
                padding: "12px",
                borderRadius: "10px",
                cursor: "pointer"
              }}
            >
              Generate Auto Plan
            </button>
          </form>
        </div>
      </div>

      <div
        style={{
          background: "#fff",
          borderRadius: "16px",
          padding: "20px",
          boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
        }}
      >
        <h3 style={{ color: "#4a148c", display: "flex", gap: "10px", alignItems: "center" }}>
          <FaList />
          My Study Plans
        </h3>

        {plans.length === 0 ? (
          <p>No plans found.</p>
        ) : (
          plans.map((plan) => (
            <div
              key={plan.id}
              style={{
                border: "1px solid #eee",
                borderRadius: "12px",
                padding: "14px",
                marginTop: "12px",
                background: "#fafafa"
              }}
            >
              <p><strong>Date:</strong> {plan.study_date}</p>
              <p><strong>Topic:</strong> {plan.topic}</p>
              <p><strong>Course ID:</strong> {plan.course_id}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default Planner;
